\label{lem:F_monotone}
The Fisher information matrix ${\mathcal F}_k$ satisfies ${\mathcal F}_{k+1}\succeq {\mathcal F}_k$ for all $k$, surely.

Consequently, $\lambda_{\min}({\mathcal F}_k)$ is a nondecreasing real-valued sequence, for every sample path.

\label{lem:sinusoidal_PE}
Let $\omega_1,\ldots,\omega_n$ be distinct frequencies in $(0,\pi)$, and define
\begin{align}
    s_k
    \stackrel{\triangle}{=}
    \begin{bmatrix}
        \sin(\omega_1 k) \\
        \cos(\omega_1 k) \\
        \vdots \\
        \sin(\omega_n k) \\
        \cos(\omega_n k)
    \end{bmatrix}
    \in
    {\mathbb R}^{2n}.
    \label{eq:s_k_def}
\end{align}
Then the sequence $\{s_k\}$ is persistently exciting.

For each $\omega_j$, the sequences
$\sin(\omega_j k)$ and $\cos(\omega_j k)$ are linearly independent.
Furthermore, sinusoidal sequences associated with distinct frequencies in $(0,\pi)$ are linearly independent.
Consequently, there exist an integer $N>0$ and a scalar $\alpha_s>0$ such that
\begin{align}
    \sum_{i=k}^{k+N-1}
        s_i s_i^{\rm T}
        &\geq
        \alpha_s I_{2n}
    \label{eq:sinusoidal_basis_PE}
\end{align}
for all $k$.
Thus, $\{s_k\}$ is persistently exciting.

\label{prop:constant_sigma}
Consider the system \eqref{eq:system} with input \eqref{eq:nominal_plus_white_noise} and $\sigma_k\equiv\sigma>0$.

Let $\phi_k^w$ be the steady-state regressor generated by $w_k$, and assume $R_w\stackrel{\triangle}{=}\mathbb E[\phi_k^w(\phi_k^w)^{\rm T}]\succ0$.

Define ${\mathcal F}_k^w\stackrel{\triangle}{=}\sum_{i=0}^{k-1}\sigma^2\phi_i^w(\phi_i^w)^{\rm T}$ and $\bar P_k\stackrel{\triangle}{=}\left(P_0^{-1}+\mathbb E[{\mathcal F}_k^w]\right)^{-1}$.

Then the following hold.
\begin{enumerate}
    \item[(a)] $\mathbb E[\phi_k\phi_k^{\rm T}]\succeq\sigma^2R_w$ for all $k$.

    Consequently, for every integer $N>0$,
    \begin{align}
        \mathbb E\left[\sum_{i=k}^{k+N-1}\phi_i\phi_i^{\rm T}\right]
            &\succeq
            N\sigma^2\lambda_{\min}(R_w)I_{2n},
        \nonumber
    \end{align}
    so $\{\phi_k\}$ is persistently exciting in expectation.

    \item[(b)] $\mathbb E[{\mathcal F}_k^w]=k\sigma^2R_w$ and
    \begin{align}
        \lambda_{\max}(\bar P_k)
            &\leq
            \frac{1}{\lambda_{\min}(P_0^{-1})+k\sigma^2\lambda_{\min}(R_w)}
            \nonumber \\
            &=
            {\mathcal O}\left((k\sigma^2)^{-1}\right).
        \label{eq:P_decay_rate}
    \end{align}
\end{enumerate}

\label{prob:main}
Given the system \eqref{eq:system}, a nominal input $\bar u_k$ that is not persistently exciting, and the RLS estimator \eqref{eq:rls_theta}--\eqref{eq:rls_P} with input \eqref{eq:nominal_plus_white_noise}, determine $\sigma_k$ as a function of quantities available online at time $k$ such that, almost surely,
\begin{align}
    \text{(i) } \sigma_k \rightarrow 0,
    \qquad
    \text{(ii) } \hat\theta_k \rightarrow \theta.
\end{align}

\label{prop:information_bound}
Consider the system \eqref{eq:system} with input \eqref{eq:nominal_plus_white_noise} and excitation amplitude \eqref{eq:self_regulating_sigma}, $0<\beta<1$.

Assume that $\{\bar u_k\}$ is bounded.

Assume that $\{w_k\}$ has finite support, that is, $|w_k|\leq\bar w$ for some $\bar w>0$, and that $w_k$ is independent of ${\mathcal H}_{k-1}$.

Then $\|\phi_k\|^2\leq B$ for all $k$ almost surely, for some $B>0$.

Moreover, with $N=2n+1$, there exists $c>0$ such that
\begin{align}
    {\mathbb E}
    \left[
        {\mathcal F}_{k+N}-{\mathcal F}_k
        \mid
        {\mathcal H}_{k-1}
    \right]
        &\succeq
        c\,\sigma_{k-1}^2 I_{2n}
    \label{eq:self_regulating_information_bound}
\end{align}
for all $k\geq1$.

Using \eqref{eq:regressor_sinusoidal_mapping},
\begin{align}
    \sum_{i=k}^{k+N-1}
        \phi_i\phi_i^{\rm T}
        &=
        H
        \left(
            \sum_{i=k}^{k+N-1}
                s_i s_i^{\rm T}
        \right)
        H^{\rm T}.
        \nonumber
\end{align}
By Lemma \ref{lem:sinusoidal_PE}, there exist an integer $N>0$ and a scalar
$\alpha_s>0$ such that
\begin{align}
    \sum_{i=k}^{k+N-1}
        s_i s_i^{\rm T}
        &\geq
        \alpha_s I_{2n}
        \nonumber
\end{align}
for all $k$.
Therefore,
\begin{align}
    \sum_{i=k}^{k+N-1}
        \phi_i\phi_i^{\rm T}
        &\geq
        \alpha_s H H^{\rm T}.
        \nonumber
\end{align}
Since $\operatorname{rank} H=2n$, the matrix $H$ is nonsingular, and thus
$$
H H^{\rm T}
    \geq
    \sigma_{\min}^2(H) I_{2n},
$$
where $\sigma_{\min}(H)>0$ is the minimum singular value of $H$.
Consequently,
\begin{align}
    \sum_{i=k}^{k+N-1}
        \phi_i\phi_i^{\rm T}
        &\geq
        \alpha_s
        \sigma_{\min}^2(H)
        I_{2n}.
        \nonumber
\end{align}
Thus, $\{\phi_k\}$ is persistently exciting.

In steady state,
\begin{align}
    \mathbb E
    \left[
        \sum_{i=k}^{k+N-1}
            \phi_i\phi_i^{\rm T}
    \right]
        &=
        \sum_{i=k}^{k+N-1}
            \mathbb E
            \left[
                \phi_i\phi_i^{\rm T}
            \right]
        =
        N R_\phi.
        \nonumber
\end{align}
Since $
R_\phi
    \geq
    \lambda_{\min}(R_\phi)I_{2n},
$
it follows that 
\begin{align}
    \mathbb E
    \left[
        \sum_{i=k}^{k+N-1}
            \phi_i\phi_i^{\rm T}
    \right]
        &\geq
        N\lambda_{\min}(R_\phi)I_{2n}
    \nonumber.
\end{align}
Thus, $\{\phi_k\}$ is persistently exciting in expectation.
